var import_zod8 = require("zod");
function createPaperContext(client, initialState = {}) {
  return {
    client,
    state: { balance: initialState.balance ?? 1e4, positions: initialState.positions ?? [], history: initialState.history ?? [] }
  };
}
function pnl(position, price) {
  const direction = position.side === "LONG" ? 1 : -1;
  return (price - position.entryPrice) * position.quantity * direction;
}
function paperTools(ctx) {
  const s = ctx.state;
  const t = ctx.client.futures.market;
  return [
    {
      name: "paper_init",
      description: "Initialize paper-trading state (reset balances, positions, history). No API keys required.",
      inputSchema: import_zod8.z.object({ balance: import_zod8.z.number().positive().default(1e4).describe("Starting USDT balance") }),
      handler: async ({ balance }) => {
        s.balance = balance;
        s.positions = [];
        s.history = [];
        return textResult(s);
      }
    },
    {
      name: "paper_balance",
      description: "Get current paper-trading balance and open-position equity (uses live market prices if an open position exists). No API keys required.",
      inputSchema: import_zod8.z.object({}),
      handler: async () => textResult(s)
    },
    {
      name: "paper_open_position",
      description: "Open an in-memory paper position at the live ticker price (or a fixed price). No API keys required.",
      inputSchema: import_zod8.z.object({
        symbol: import_zod8.z.string().min(1).describe("USD-M pair, e.g. BTCUSDT"),
        side: import_zod8.z.enum(["LONG", "SHORT"]),
        quantity: import_zod8.z.number().positive(),
        price: import_zod8.z.number().positive().optional().describe("If omitted, uses live ticker price")
      }),
      handler: async ({ symbol: symbol3, side: side3, quantity, price }) => {
        const sym = normalizeSymbol(symbol3);
        const market = price ?? Number((await t.tickerPrice(sym)).price);
        const position = { id: Date.now().toString(), symbol: sym, side: side3, quantity, entryPrice: market, openedAt: (/* @__PURE__ */ new Date()).toISOString() };
        s.positions.push(position);
        s.history.push({ type: "open", ...position });
        return textResult(position);
      }
    },
    {
      name: "paper_close_position",
      description: "Close a paper position by id (or symbol) and realize PnL at the live/last price.",
      inputSchema: import_zod8.z.object({
        id: import_zod8.z.string().optional().describe("Position id from paper_open_position"),
        symbol: import_zod8.z.string().min(1).optional().describe("Close the position for this symbol"),
        price: import_zod8.z.number().positive().optional().describe("If omitted, uses live ticker price")
      }),
      handler: async ({ id, symbol: symbol3, price }) => {
        const idx = s.positions.findIndex((p) => id ? p.id === id : normalizeSymbol(p.symbol) === normalizeSymbol(symbol3 ?? ""));
        if (idx === -1) throw new Error("paper position not found");
        const position = s.positions[idx];
        const market = price ?? Number((await t.tickerPrice(position.symbol)).price);
        const realizedPnl = pnl(position, market);
        s.balance += realizedPnl;
        const closed = { type: "close", ...position, exitPrice: market, realizedPnl, closedAt: (/* @__PURE__ */ new Date()).toISOString() };
        s.positions.splice(idx, 1);
        s.history.push(closed);
        return textResult(closed);
      }
    },
    {
      name: "paper_positions",
      description: "List open paper positions with live unrealized PnL (marked to market).",
      inputSchema: import_zod8.z.object({}),
      handler: async () => {
        const out = await Promise.all(
          s.positions.map(async (p) => {
            const price = Number((await t.tickerPrice(p.symbol)).price);
            return { ...p, markPrice: price, unrealizedPnl: pnl(p, price) };
          })
        );
        return textResult(out);
      }
    },
    {
      name: "paper_history",
      description: "List paper-trading history of open/close events with realized PnL.",
      inputSchema: import_zod8.z.object({}),
      handler: async () => textResult(s.history)
    },
    {
      name: "paper_summary",
      description: "Summarize paper-trading state: balance, open positions, trade count.",
      inputSchema: import_zod8.z.object({}),
      handler: async () => textResult({ balance: s.balance, openPositions: s.positions.length, trades: s.history.length })
    }
  ];
}

